"""FastAPI download endpoint with HTTP Range (bytes) support.

GET /files/report.bin
  - deterministic 1 MiB payload generated from a seeded PRNG at startup
  - Accept-Ranges: bytes advertised on every response
  - single range requests  -> 206 + Content-Range: bytes <start>-<end>/<size>
      bytes=0-1023   first 1024 bytes
      bytes=500-     from offset 500 to EOF
      bytes=-256     last 256 bytes (suffix form)
  - unsatisfiable range    -> 416 + Content-Range: bytes */1048576
  - no/ignored Range       -> plain 200 with the whole file
"""

import random
import re
from typing import Optional, Tuple

from fastapi import FastAPI, Request, Response

SEED = 20260824
FILE_SIZE = 1 * 1024 * 1024  # 1 MiB
MEDIA_TYPE = "application/octet-stream"

app = FastAPI(title="range-demo")


def build_payload(size: int, seed: int) -> bytes:
    """Deterministic pseudo-random bytes; identical on every startup."""
    rng = random.Random(seed)
    return rng.randbytes(size)


# Generated once at import time ("at startup" for the service).
DATA: bytes = build_payload(FILE_SIZE, SEED)

_RANGE_RE = re.compile(r"^bytes=(\d*)-(\d*)$")
ACCEPT_RANGES = {"Accept-Ranges": "bytes"}


def parse_single_range(header: str) -> Optional[Tuple[int, int]]:
    """Parse one byte-range-spec into an inclusive (start, end) pair.

    Returns None if the header is syntactically invalid or is a multi-range
    request -> per RFC 9110 the header should be ignored and the full body
    returned. Raises ValueError for a *syntactically valid but unsatisfiable*
    range.
    """
    m = _RANGE_RE.match(header.strip())
    if not m:
        return None  # malformed or "bytes=a-b,c-d" -> ignore, serve full file
    first, last = m.group(1), m.group(2)

    if first == "" and last == "":
        return None  # "bytes=-" is invalid -> ignore

    if first == "":
        # Suffix form: last N bytes. N == 0 can never be satisfied.
        n = int(last)
        if n == 0:
            raise ValueError("zero-length suffix range")
        start = max(0, FILE_SIZE - n)
        end = FILE_SIZE - 1
    else:
        start = int(first)
        end = min(int(last), FILE_SIZE - 1) if last != "" else FILE_SIZE - 1
        if start > int(last) and last != "":
            return None  # inverted range like bytes=999-99 -> ignore
        if start >= FILE_SIZE:
            raise ValueError("start offset beyond EOF")

    return start, end


@app.get("/files/report.bin")
def download_report(request: Request) -> Response:
    range_header = request.headers.get("range")

    if range_header:
        try:
            rng = parse_single_range(range_header)
        except ValueError:
            return Response(
                status_code=416,
                media_type=MEDIA_TYPE,
                headers={
                    **ACCEPT_RANGES,
                    "Content-Range": f"bytes */{FILE_SIZE}",
                },
            )
        if rng is not None:
            start, end = rng
            return Response(
                content=DATA[start : end + 1],
                status_code=206,
                media_type=MEDIA_TYPE,
                headers={
                    **ACCEPT_RANGES,
                    "Content-Range": f"bytes {start}-{end}/{FILE_SIZE}",
                    "Content-Length": str(end - start + 1),
                },
            )

    # No Range header (or ignored): plain full-body 200.
    return Response(
        content=DATA,
        media_type=MEDIA_TYPE,
        headers={**ACCEPT_RANGES, "Content-Length": str(FILE_SIZE)},
    )

